set -euo pipefail; python3 - <<'PY'
import base64, gzip, math, re, subprocess, time
from pathlib import Path
import serial

PORT='/dev/cu.usbserial-130'
subprocess.run(['git','fetch','origin','agent-control'], check=True, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
parts=[]
for i in range(6):
    path=f'.agent/payloads/kobra-lemur10-live/chunk{i:02d}.b64'
    parts.append(subprocess.check_output(['git','show',f'origin/agent-control:{path}'], text=True).strip())
blob=''.join(parts)
raw=gzip.decompress(base64.b64decode(blob, validate=True)).decode('utf-8')
lines=raw.splitlines()
active=[]
for n,line in enumerate(lines,1):
    s=line.split(';',1)[0].strip()
    if s:
        active.append((n,s))
if not active or active[0][1] != 'G90' or active[-1][1] != 'M400':
    raise SystemExit('preflight: bad first/last command')
allowed={'G90','G0','G1','M400'}
minx=miny=1e9; maxx=maxy=-1e9
for n,s in active:
    p=s.split(); cmd=p[0].upper()
    if cmd not in allowed:
        raise SystemExit(f'preflight line {n}: forbidden command {cmd}')
    if cmd in {'G90','M400'}:
        if len(p)!=1: raise SystemExit(f'preflight line {n}: params on {cmd}')
        continue
    vals={}
    for tok in p[1:]:
        m=re.fullmatch(r'([A-Za-z])([-+]?\d+(?:\.\d+)?)',tok)
        if not m: raise SystemExit(f'preflight line {n}: malformed token {tok}')
        vals[m.group(1).upper()]=float(m.group(2))
    if 'E' in vals: raise SystemExit(f'preflight line {n}: extrusion forbidden')
    has_xy='X' in vals or 'Y' in vals; has_z='Z' in vals
    if has_xy == has_z: raise SystemExit(f'preflight line {n}: mixed/empty motion')
    if has_z:
        if cmd!='G0' or set(vals)!={'Z','F'} or vals['Z'] not in {3.12,6.12} or vals['F']!=180:
            raise SystemExit(f'preflight line {n}: invalid Z motion {s}')
    else:
        if set(vals)!={'X','Y','F'}: raise SystemExit(f'preflight line {n}: invalid XY params')
        x,y=vals['X'],vals['Y']
        if not (8.0 <= x <= 218.0 and 41.0 <= y <= 225.0):
            raise SystemExit(f'preflight line {n}: XY out of bounds {x},{y}')
        if cmd=='G0' and vals['F']!=3000: raise SystemExit(f'preflight line {n}: bad travel feed')
        if cmd=='G1' and vals['F']!=1200: raise SystemExit(f'preflight line {n}: bad draw feed')
        minx=min(minx,x); maxx=max(maxx,x); miny=min(miny,y); maxy=max(maxy,y)
print(f'PREFLIGHT_OK commands={len(active)} bounds=X[{minx:.2f},{maxx:.2f}] Y[{miny:.2f},{maxy:.2f}]', flush=True)
if not Path(PORT).exists(): raise SystemExit(f'port missing: {PORT}')

def wait_ok(ser, timeout=30.0):
    deadline=time.monotonic()+timeout
    while time.monotonic()<deadline:
        b=ser.readline()
        if not b: continue
        t=b.decode('utf-8',errors='replace').strip()
        if not t: continue
        lo=t.lower()
        if lo.startswith('error') or 'printer halted' in lo or 'kill() called' in lo:
            raise RuntimeError(t)
        if lo=='ok' or lo.startswith('ok '): return
    raise TimeoutError('timeout waiting for ok')

started=False
with serial.Serial(PORT,115200,timeout=0.25,write_timeout=2) as ser:
    time.sleep(2.0); ser.reset_input_buffer()
    try:
        total=len(active)
        print('LIVE_START', flush=True); started=True
        for idx,(n,s) in enumerate(active,1):
            ser.write((s+'\n').encode('ascii')); ser.flush(); wait_ok(ser, 60.0 if s=='M400' else 30.0)
            if idx==1 or idx%500==0 or idx==total:
                print(f'PROGRESS {idx}/{total}', flush=True)
        print('LIVE_COMPLETE', flush=True)
    except Exception as exc:
        print(f'LIVE_ABORT {type(exc).__name__}: {exc}', flush=True)
        if started:
            try:
                ser.write(b'G0 Z6.12 F180\n'); ser.flush(); wait_ok(ser,10.0)
                ser.write(b'M400\n'); ser.flush(); wait_ok(ser,20.0)
                print('PEN_UP_AFTER_ABORT_OK', flush=True)
            except Exception as rescue:
                print(f'PEN_UP_AFTER_ABORT_FAILED: {rescue}', flush=True)
        raise
PY
